import { useState, useEffect } from "react";//use effect hook 3lshan y3ml fetch lel data mn el backend lma el page tft7
import { useAuth } from "../context/AuthContext";// useAuth 3lshan ngeb el token 
const API_URL = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

function AdminOverview() {
  const { token } = useAuth();// bngeeb el token

  // state variables 3lshan n7ot feha el data ely hgeebha mn el backend 
  const [orders, setOrders]     = useState([]);
  const [users, setUsers]       = useState([]);
  const [products, setProducts] = useState([]);
  const [loading, setLoading]   = useState(true);//3lshan n3rf el data gat kolha wala lesa
  const [error, setError]       = useState(null);

  useEffect(() => { fetchAll(); }, []);
  // الـ [] دي معناها اشتغل مرة واحدة بس لما الكومبوننت يتعمل mount

  const fetchAll = async () => {
    setLoading(true);
    setError(null);
    try {
      const headers = { Authorization: `Bearer ${token}` };
      // بنبعت الـ token في الـ header مع كل request محتاج صلاحيات أدمن

      // بنبعت الـ 3 requests دول في نفس الوقت مع Promise.all عشان منستناش كل واحدة لوحدها
      const oRes = await fetch(`${API_URL}/orders`, { headers });
      const uRes = await fetch(`${API_URL}/users`, { headers });
      const pRes = await fetch(`${API_URL}/products`);

      if (!oRes.ok || !uRes.ok || !pRes.ok) throw new Error("Failed to load dashboard data");
      // لو أي request فشل ابعت error

      const [oData, uData, pData] = await Promise.all([oRes.json(), uRes.json(), pRes.json()]);
      // حوّل الـ responses لـ JSON في نفس الوقت كمان

      setOrders(Array.isArray(oData) ? oData : []);
      setUsers(Array.isArray(uData) ? uData : []);
      setProducts(Array.isArray(pData) ? pData : []);
      // Array.isArray عشان لو الباكند رجع حاجة غلط منكسرش
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
      // سواء نجح أو فشل وقف الـ loading
    }
  };

  // مش state - بس حساب بسيط من الـ orders اللي عندنا
  const totalRevenue = orders.reduce((sum, order) => sum + order.totalPrice, 0);

  // array عادية بس بتبني كاردز الإحصائيات من الداتا اللي جت
  const stats = [
    { label: "Total Products", value: products.length, icon: "bi-box-seam",        bg: "#e8f4fd", color: "#1565c0" },
    { label: "Total Orders",   value: orders.length,   icon: "bi-bag-check",       bg: "#e8f5e9", color: "#2e7d32" },
    { label: "Total Users",    value: users.length,    icon: "bi-people",          bg: "#f3e5f5", color: "#6a1b9a" },
    { label: "Revenue",        value: `$${totalRevenue.toFixed(0)}`, icon: "bi-currency-dollar", bg: "#fff3e0", color: "#e65100" },
  ];

  if (error) return <div className="alert alert-danger" style={{ borderRadius: 0 }}>{error}</div>;
  // لو في error وقف هنا وورّي الرسالة ومتكملش الـ render

  return (
    <div>
      <h4 className="serif mb-1">Dashboard Overview</h4>
      <p className="text-muted mb-4" style={{ fontSize: "0.85rem" }}>Welcome to the ArtFrame admin panel.</p>

      {/* الـ 4 كاردز بتاعت الإحصائيات */}
      <div className="row g-3 mb-4">
        {stats.map((stat) => (
          <div className="col-6 col-md-3" key={stat.label}>
            <div className="af-card p-3" style={{ cursor: "default" }}>
              <div className="d-flex align-items-center gap-2 mb-2">
                <div style={{ background: stat.bg, color: stat.color, padding: "8px", borderRadius: 4, lineHeight: 1 }}>
                  <i className={`bi ${stat.icon}`} style={{ fontSize: "1.1rem" }}></i>
                </div>
              </div>
              {loading
                ? <div className="skeleton" style={{ height: 24, width: "60%" }}></div>
                // لو لسه بيجيب البيانات ورّي skeleton
                : <p className="serif mb-0" style={{ fontSize: "1.6rem", fontWeight: 700 }}>{stat.value}</p>
                // لو البيانات جت ورّي الرقم الحقيقي
              }
              <small className="text-muted">{stat.label}</small>
            </div>
          </div>
        ))}
      </div>

      {/* آخر 5 أوردرات */}
      <h6 className="serif mb-3">Recent Orders</h6>
      {loading ? (
        <div className="skeleton" style={{ height: 200 }}></div>
      ) : (
        <div className="af-card" style={{ cursor: "default" }}>
          {orders.slice(0, 5).map((order, i) => (
            // slice(0,5) يعني خد أول 5 أوردرات بس
            <div
              key={order._id}
              className="d-flex justify-content-between align-items-center p-3"
              style={{ borderBottom: i < Math.min(orders.length, 5) - 1 ? "1px solid var(--border)" : "none" }}
              // بنحط border تحت كل row غير الأخيرة
            >
              <div>
                <p className="mb-0" style={{ fontWeight: 500, fontSize: "0.88rem" }}>
                  #{order._id.slice(-8).toUpperCase()}
                  {/* بناخد آخر 8 حروف من الـ id عشان يبقى أقصر */}
                </p>
                <small className="text-muted">{order.user && order.user.name || order.user && order.user.email || "User"}</small>
                {/* ?. دي optional chaining - لو user مش موجود متكسرش */}
              </div>
              <div className="text-end">
                <p className="mb-0" style={{ fontWeight: 600, fontSize: "0.88rem" }}>${order.totalPrice.toFixed(2)}</p>
                <small className="text-muted">{order.status}</small>
              </div>
            </div>
          ))}
          {orders.length === 0 && (
            <div className="p-4 text-center text-muted">No orders yet</div>
          )}
        </div>
      )}
    </div>
  );
}

export default AdminOverview;
